// Experiment 3: an agent (a local model over Ollama's OpenAI-compatible chat endpoint) operates a
// running Sygnal app through tools generated by exposeToAgents(): annotated (`agent` static)
// vs bare (every action, no metadata). Success = the app's final state, not the model's words.
import {JSDOM} from 'jsdom';
const dom = new JSDOM('<!doctype html><div id="root"></div>');
Object.assign(globalThis, {window: dom.window, document: dom.window.document, Node: dom.window.Node, HTMLElement: dom.window.HTMLElement, Element: dom.window.Element, Event: dom.window.Event, requestAnimationFrame: f => setTimeout(f, 16)});
const {run, makeDOMDriver, createElement: h} = await import('sygnal');
const {exposeToAgents, fakeModelContext} = await import('./exposeToAgents.js');

function Filter({state}) { return h('nav', null, ['all', 'active', 'done'].map(f => h('button', {class: {sel: state === f}, 'data-f': f}, f))); }
Filter.intent = ({DOM}) => ({SET_FILTER: DOM.select('button').events('click').map(e => e.target.dataset.f)});
Filter.model = {SET_FILTER: (s, f) => f};
Filter.agent = {
  description: 'the todo list filter',
  actions: {SET_FILTER: {description: 'Show all, only active (not done), or only done todos', input: {type: 'string', enum: ['all', 'active', 'done']}}},
};

function TodoApp({state}) {
  return h('main', null, h('input', {class: 'new'}),
    h('ul', null, state.todos.map(t => h('li', {class: {done: t.done}}, t.text))),
    h(Filter, {state: 'filter'}));
}
TodoApp.initialState = {todos: [{id: 1, text: 'water plants', done: false}], filter: 'all', nextId: 2};
TodoApp.intent = ({DOM}) => ({ADD: DOM.select('.new').events('change').map(e => e.target.value)});
TodoApp.model = {
  ADD: (s, text) => ({...s, todos: [...s.todos, {id: s.nextId, text, done: false}], nextId: s.nextId + 1}),
  TOGGLE: (s, id) => ({...s, todos: s.todos.map(t => t.id === id ? {...t, done: !t.done} : t)}),
  REMOVE: (s, id) => ({...s, todos: s.todos.filter(t => t.id !== id)}),
  CLEAR_DONE: s => ({...s, todos: s.todos.filter(t => !t.done)}),
};
TodoApp.agent = {
  description: 'the todo list',
  state: s => ({todos: s.todos}),
  actions: {
    ADD: {description: 'Add a todo with this text', input: {type: 'string'}},
    TOGGLE: {description: 'Mark the todo with this id done (or not done again)', input: {type: 'integer', description: 'todo id'}},
    REMOVE: {description: 'Delete the todo with this id', input: {type: 'integer'}, destructive: true},
  },
};

const TASK = "Add todos 'buy milk' and 'call mom'. Mark 'water plants' as done. Then make the list show only active todos.";
const success = s => s.todos.some(t => String(t.text).toLowerCase().includes('buy milk') && !t.done) && s.todos.some(t => /call mom/i.test(String(t.text)) && !t.done)
  && s.todos.some(t => t.text === 'water plants' && t.done) && s.todos.length === 3 && s.filter === 'active';

async function agent(model, mc, maxSteps = 12, withContext = false) {
  const tools = mc.listTools().map(t => ({type: 'function', function: {name: t.name, description: t.description, parameters: t.inputSchema}}));
  const ctx = withContext ? '\nCurrent app state:\n' + (await Promise.all(mc.listTools().filter(t => t.name.endsWith('read_state')).map(async t => `${t.name.replace('_read_state', '')}: ${(await mc.callTool(t.name)).content[0].text}`))).join('\n') : '';
  const messages = [{role: 'system', content: 'You operate a web app through its tools. Call tools to do the task, then reply DONE.' + (/qwen/.test(model) ? ' /no_think' : '') + ctx}, {role: 'user', content: TASK}];
  let calls = 0;
  agent.trace = [];
  for (let i = 0; i < maxSteps; i++) {
    const res = await fetch('http://localhost:11434/v1/chat/completions', {method: 'POST', headers: {'content-type': 'application/json'}, body: JSON.stringify({model, messages, tools, temperature: 0.2}), signal: AbortSignal.timeout(180000)}).then(r => r.json()).catch(e => ({error: String(e)}));
    if (res.error) break;
        const msg = res.choices[0].message;
    messages.push(msg);
    if (!msg.tool_calls?.length) break;
    for (const c of msg.tool_calls) {
      calls++;
      let args = {};
      try { args = JSON.parse(c.function.arguments || '{}'); } catch {}
      const out = await mc.callTool(c.function.name, args);
      agent.trace.push(`${c.function.name}(${c.function.arguments})`);
      messages.push({role: 'tool', tool_call_id: c.id, content: out.content[0].text});
    }
  }
  return calls;
}

const model = process.argv[2] || 'llama3.2';
const N = +(process.argv[3] || 5);
const rows = [];
for (const mode of (process.argv[4] || 'bare,annotated,validated,context').split(',')) {
  let ok = 0, calls = 0, ms = 0, toolCount;
  for (let i = 0; i < N; i++) {
    document.body.innerHTML = '<div id="root"></div>';
    const app = run(TodoApp, {DOM: makeDOMDriver('#root')});
    await app.__runtime.flushed();
    const mc = fakeModelContext();
    const stop = exposeToAgents(app, {modelContext: mc, mode: mode === 'context' ? 'validated' : mode});
    toolCount = mc.listTools().length;
    if (i === 0 && mode === 'annotated') console.log('tools:', mc.listTools().map(t => t.name).join(', '));
    const t0 = performance.now();
    calls += await agent(model, mc, 12, mode === 'context');
    ms += performance.now() - t0;
    const s = app.__runtime.getState();
    const good = success(s);
    ok += good;
    if (!good && i < 2) console.log(`${mode} fail: calls ${agent.trace.join(' ')} → ${JSON.stringify(s.todos.map(t => [t.id, t.text, t.done]))} filter=${JSON.stringify(s.filter)}`);
    // the DOM reflects what the agent did: the same app a person sees
    if (i === 0) console.log(`${mode} DOM:`, document.querySelector('ul').textContent, '| filter button:', document.querySelector('button.sel')?.textContent);
    stop(); app.dispose();
  }
  rows.push({model, mode, tools: toolCount, success: `${ok}/${N}`, avgToolCalls: (calls / N).toFixed(1), avgSec: (ms / N / 1000).toFixed(1)});
}
console.table(rows);
process.exit(0);
